import React, { useState } from 'react'
import { Modal } from 'antd';
import { Viewer } from '@react-pdf-viewer/core';


function ViewContractPDFModal({openPDFModal,setopenPDFModal,contractUrl}) {


return (
    <Modal
        className="overflow-y-scroll max-h-lvh"
        open={openPDFModal}
        title="View Contract PDF"
        footer={null}
        width={800}
        style={{ height: 600, top: 20, padding: 0, position: 'relative' }}
        destroyOnClose
        onClose={() => setopenPDFModal(false)}
        onCancel={() => setopenPDFModal(false)}
    >

          <Viewer fileUrl={contractUrl} />  

    </Modal>
)
}

export default ViewContractPDFModal